\copy (SELECT e.signal_date, e.side, e.signal_type, e.split_key, e.exit_reason, e.holding_days, e.gross_ret::float, e.net_ret::float, e.mfe::float, e.mae::float, e.entry_price::float, e.atr_14::float, e.above_sma200, e.dd_bucket, e.cofire_count, e.is_cluster_head, e.fwd_ret_5d::float, (SELECT m.breadth_ma_above FROM market_days m WHERE m.ts < e.signal_date ORDER BY m.ts DESC LIMIT 1)::float AS breadth, (SELECT m.spx_close FROM market_days m WHERE m.ts < e.signal_date ORDER BY m.ts DESC LIMIT 1)::float AS spx_prev, e.exit_date FROM events e WHERE e.config_hash='f183b0f5209a4677' AND e.entry_kind='touch' AND e.in_trade AND e.exit_reason IS NOT NULL AND e.exit_reason <> 'unfinished' AND e.net_ret IS NOT NULL) TO '/tmp/shortbook.csv' CSV HEADER
\copy (SELECT ts, spx_close::float FROM market_days WHERE spx_close IS NOT NULL ORDER BY ts) TO '/tmp/spx.csv' CSV HEADER
